def parse_filter_value(text):
    """
    Accepts:
      - 'a-b'       -&gt; (a,b)
      - 'v1,v2,...' -&gt; [v1,v2,...] (numbers auto-cast)
      - '/regex/'   -&gt; compiled regex
      - scalar      -&gt; int/float if possible else string
    """
    text = text.strip()
    if not text:
        return None
    # regex: /.../
    if len(text) &gt;= 2 and text.startswith('/') and text.endswith('/'):
        try:
            return re.compile(text[1:-1])
        except Exception:
            return text

    if '-' in text and not text.startswith('-'):
        parts = text.split('-')
        if len(parts) == 2:
            try:
                lower = float(parts[0].strip())
                upper = float(parts[1].strip())
                return (lower, upper)
            except ValueError:
                pass
    if ',' in text:
        parts = [p.strip() for p in text.split(',')]
        parsed_parts = []
        for p in parts:
            try:
                if '.' in p:
                    parsed_parts.append(float(p))
                else:
                    parsed_parts.append(int(p))
            except ValueError:
                parsed_parts.append(p)
        return parsed_parts
    try:
        if text.isdigit():
            return int(text)
        return float(text)
    except ValueError:
        return text
